    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        fn_GetParentValue();
        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_haltschdl",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_haltschdl=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_haltschdl_info",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_haltschdl_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        txb_seq.hide();
        //  정보 읽어오기
        fn_ReadInfo();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36002.onpageload" });
    }
};

/**
 * @method
