/**
 * @method
 * @name trs_haltschdl_OnSuccess
 * @description haltschdl On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_haltschdl_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36002.trs_haltschdl_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_haltschdl_OnFail
 * @description haltschdl On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_haltschdl_OnFail = async function() {
    try {
        await $c.win.alert('trs_haltschdl.OnFail() :' + trs_haltschdl.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36002.trs_haltschdl_OnFail" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    const vHaltschdlDd = edt_haltschdl_dd.getValue();
    if (vHaltschdlDd > 0 && vHaltschdlDd.length < 8) {
        await $c.win.alert("매매거래정지예정일을 올바르게 입력하시오.");
        edt_haltschdl_dd.focus();
        return;
    }
    const vReleasDd = edt_releas_dd.getValue();
    if (vReleasDd > 0 && vReleasDd.length < 8) {
        await $c.win.alert("매매거래해제예정일을 올바르게 입력하시오.");
        edt_releas_dd.focus();
        return;
    }
    const vNewschdlDd = edt_newschdl_dd.getValue();
    if (vNewschdlDd > 0 && vNewschdlDd.length < 8) {
        await $c.win.alert("신주권교부예정일을 올바르게 입력하시오.");
        edt_newschdl_dd.focus();
        return;
    }
    const vListschdlDd = edt_listschdl_dd.getValue();
    if (vListschdlDd > 0 && vListschdlDd.length < 8) {
        await $c.win.alert("상장예정일을 올바르게 입력하시오.");
        edt_listschdl_dd.focus();
        return;
    }
    dts_haltschdl.insertRow();
    dts_haltschdl.setCellData(1, "SEQ", scwin.gSeq);
    dts_haltschdl.setCellData(1, "HALT_SCHDL_DD", vHaltschdlDd);
    dts_haltschdl.setCellData(1, "HALT_RELEAS_SCHDL_DD", vReleasDd);
    dts_haltschdl.setCellData(1, "NEWSTK_SCHDL_DD", vNewschdlDd);
    dts_haltschdl.setCellData(1, "LIST_SCHDL_DD", vListschdlDd);
    dts_haltschdl.setCellData(1, "REMK", txa_remk.getValue());

    // alert(dts_haltschdl.text);

    let vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        // alert(dts_again.text);
        trs_haltschdl.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_haltschdl",
            action : "/TrdHaltSchdl.do",
            ref : "dts_haltschdl",
            target : "trs_haltschdl=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    dts_haltschdl.insertRow();
    dts_haltschdl.setCellData(1, "SEQ", scwin.gSeq);
    dts_haltschdl.setCellData(1, "EMP_NO", js_emp_no);

    // alert(dts_haltschdl.text);

    let vAnswer = confirm('삭제 하시겠습니까?');
    if (vAnswer === true) {
        // alert(dts_again.text);
        trs_haltschdl.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_haltschdl",
            action : "/TrdHaltSchdl.do",
            ref : "dts_haltschdl",
            target : "trs_haltschdl=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
